import requests
from bs4 import BeautifulSoup

class Scraper:
    def __init__(self):
        self.data = {}

    def scrape(self, category):
        response = requests.get(f'https://quotes.toscrape.com/random')
        soup = BeautifulSoup(response.text, 'lxml')
        quote = soup.find('span', class_='text').get_text()
        author = soup.find('span', class_='author').get_text()
        tags = soup.find('div', class_='tags').find_all('a')

        self.data[category] = {
            'quote': quote,
            'author': author,
            'tags': {tag.get_text() for tag in tags}
        }

