def register_all():
    users = [
        {'username': 'jane_doe', 'gender': 'Female'},
        {'username': 'john_doe', 'gender': 'Male'}
    ]

    query = "INSERT INTO users (username, gender) VALUES ("
    for user in users:
        query += f"('{user['username']}', '{user['gender']}'),"

    query = query[:-1] + ")"

    db.session.execute(query)
    db.session.commit()

    return jsonify({'status': 'Users registered successfully'})

